CREATE TRIGGER trg_t3f_prior_usage_retention_bi BEFORE INSERT ON tenant_database_purge_receipts FOR EACH ROW BEGIN IF NEW.prior_retained_billing_facts_json IS NULL OR NEW.prior_retained_billing_facts_sha256 IS NULL OR NOT (NEW.prior_retained_billing_facts_sha256 REGEXP '^[0-9a-f]{64}$') OR NOT (JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["schemaVersion","facts","evidenceSha256"],"properties":{"schemaVersion":{"type":"integer","enum":[1]},"evidenceSha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"facts":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["usageId","factSha256"],"properties":{"usageId":{"type":"string","pattern":"^usg_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"factSha256":{"type":"string","pattern":"^[0-9a-f]{64}$"}}}}}}',NEW.prior_retained_billing_facts_json) <=> 1) OR NOT (JSON_UNQUOTE(JSON_EXTRACT(NEW.prior_retained_billing_facts_json,'$.evidenceSha256')) <=> NEW.prior_retained_billing_facts_sha256) OR NOT (JSON_LENGTH(JSON_EXTRACT(NEW.prior_retained_billing_facts_json,'$.facts')) <= NEW.retained_billing_fact_count) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='T3f requires explicit prior retained usage bridge'; END IF; END;
CREATE TRIGGER trg_session_grave_usage_retention_bi BEFORE INSERT ON tenant_purge_session_grave_markers FOR EACH ROW BEGIN IF (NEW.ordinary_usage_retention_source_sha256 IS NULL AND NEW.ordinary_usage_retention_receipt_sha256 IS NOT NULL) OR (NEW.ordinary_usage_retention_source_sha256 IS NOT NULL AND NOT (NEW.ordinary_usage_retention_source_sha256 REGEXP '^[0-9a-f]{64}$')) OR (NEW.ordinary_usage_retention_receipt_sha256 IS NOT NULL AND NOT (NEW.ordinary_usage_retention_receipt_sha256 REGEXP '^[0-9a-f]{64}$')) OR NOT EXISTS (SELECT 1 FROM sessions s WHERE s.session_id=NEW.session_id AND s.tenant_id=NEW.tenant_id AND (NEW.ordinary_usage_retention_source_sha256 IS NULL OR s.deletion_generation=NEW.deletion_generation) AND s.ordinary_usage_retention_source_sha256 <=> NEW.ordinary_usage_retention_source_sha256 AND s.ordinary_usage_retention_receipt_sha256 <=> NEW.ordinary_usage_retention_receipt_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='session grave ordinary usage proof requires exact live source'; END IF; END;
CREATE TRIGGER trg_sessions_usage_retention_bi BEFORE INSERT ON sessions FOR EACH ROW BEGIN IF NEW.ordinary_usage_retention_source_json IS NOT NULL OR NEW.ordinary_usage_retention_source_sha256 IS NOT NULL OR NEW.ordinary_usage_retention_receipt_json IS NOT NULL OR NEW.ordinary_usage_retention_receipt_sha256 IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention cannot be supplied at session creation'; END IF; END;
CREATE TRIGGER trg_sessions_usage_retention_shape_bu BEFORE UPDATE ON sessions FOR EACH ROW BEGIN IF (NEW.ordinary_usage_retention_source_json IS NULL) <> (NEW.ordinary_usage_retention_source_sha256 IS NULL) OR (NEW.ordinary_usage_retention_receipt_json IS NULL) <> (NEW.ordinary_usage_retention_receipt_sha256 IS NULL) OR (NEW.ordinary_usage_retention_source_json IS NULL AND NEW.ordinary_usage_retention_receipt_json IS NOT NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention partial evidence'; END IF; IF NEW.ordinary_usage_retention_source_json IS NOT NULL THEN IF NOT (JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["schemaVersion","originSha256","policyVersion","policySha256"],"properties":{"schemaVersion":{"type":"integer","enum":[2]},"originSha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"policyVersion":{"anyOf":[{"type":"null"},{"type":"string","minLength":1,"maxLength":128}]},"policySha256":{"anyOf":[{"type":"null"},{"type":"string","pattern":"^[0-9a-f]{64}$"}]}}}',NEW.ordinary_usage_retention_source_json) <=> 1) OR NOT (JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_source_json,'$.originSha256')) <=> NEW.ordinary_delete_origin_sha256) OR NOT (NEW.ordinary_usage_retention_source_sha256 REGEXP '^[0-9a-f]{64}$') OR NOT ((JSON_TYPE(JSON_EXTRACT(NEW.ordinary_usage_retention_source_json,'$.policyVersion')) <=> 'NULL') = (JSON_TYPE(JSON_EXTRACT(NEW.ordinary_usage_retention_source_json,'$.policySha256')) <=> 'NULL')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention source shape invalid'; END IF; END IF; IF NEW.ordinary_usage_retention_receipt_json IS NOT NULL THEN IF NOT (JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"required":["schemaVersion","sourceSha256","sealSha256","deletionPolicySha256","currentPolicySha256","currentPolicyVersion","deadlineDbMs","executedAtDbMs","checksum","facts","allDomainsComplete","contentPurgeExecuted"],"properties":{"schemaVersion":{"type":"integer","enum":[1]},"sourceSha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"sealSha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"deletionPolicySha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"currentPolicySha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"currentPolicyVersion":{"type":"string","minLength":1,"maxLength":128},"deadlineDbMs":{"type":"integer","minimum":0,"maximum":9007199254740991},"executedAtDbMs":{"type":"integer","minimum":0,"maximum":9007199254740991},"checksum":{"type":"string","pattern":"^[0-9a-f]{64}$"},"facts":{"type":"array","maxItems":10000,"items":{"type":"object","additionalProperties":false,"required":["usageId","factSha256"],"properties":{"usageId":{"type":"string","pattern":"^usg_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"factSha256":{"type":"string","pattern":"^[0-9a-f]{64}$"}}}},"allDomainsComplete":{"type":"boolean","enum":[false]},"contentPurgeExecuted":{"type":"boolean","enum":[false]}}}',NEW.ordinary_usage_retention_receipt_json) <=> 1) OR NOT (JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.sourceSha256')) <=> NEW.ordinary_usage_retention_source_sha256) OR NOT (JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.sealSha256')) <=> NEW.ordinary_delete_seal_sha256) OR NOT (JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.deletionPolicySha256')) <=> JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_source_json,'$.policySha256'))) OR NOT (CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.deadlineDbMs')) AS UNSIGNED) >= NEW.ordinary_delete_grace_floor_db_ms) OR NOT (CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.executedAtDbMs')) AS UNSIGNED) >= CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.deadlineDbMs')) AS UNSIGNED)) OR NOT (NEW.ordinary_usage_retention_receipt_sha256 REGEXP '^[0-9a-f]{64}$') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention receipt shape invalid'; END IF; END IF; END;
CREATE TRIGGER trg_sessions_usage_retention_bu BEFORE UPDATE ON sessions FOR EACH ROW BEGIN IF OLD.ordinary_usage_retention_source_json IS NOT NULL THEN IF NOT (NEW.ordinary_usage_retention_source_json <=> OLD.ordinary_usage_retention_source_json) OR NOT (NEW.ordinary_usage_retention_source_sha256 <=> OLD.ordinary_usage_retention_source_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention source is immutable'; END IF; ELSEIF NEW.ordinary_usage_retention_source_json IS NOT NULL OR NEW.ordinary_usage_retention_source_sha256 IS NOT NULL THEN IF OLD.deleted_at_ms IS NOT NULL OR OLD.ordinary_delete_origin_sha256 IS NOT NULL OR NEW.deleted_at_ms IS NULL OR NEW.ordinary_delete_origin_sha256 IS NULL OR NEW.ordinary_usage_retention_source_json IS NULL OR NEW.ordinary_usage_retention_source_sha256 IS NULL OR JSON_EXTRACT(NEW.ordinary_usage_retention_source_json,'$.schemaVersion') <> 2 OR JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_source_json,'$.originSha256')) <> NEW.ordinary_delete_origin_sha256 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention source requires first ordinary tombstone'; END IF; END IF; IF OLD.ordinary_delete_origin_sha256 IS NULL AND NEW.ordinary_delete_origin_sha256 IS NOT NULL AND NEW.ordinary_usage_retention_source_json IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention source requires schema-aware writer'; END IF; IF OLD.ordinary_usage_retention_receipt_json IS NOT NULL THEN IF NOT (NEW.ordinary_usage_retention_receipt_json <=> OLD.ordinary_usage_retention_receipt_json) OR NOT (NEW.ordinary_usage_retention_receipt_sha256 <=> OLD.ordinary_usage_retention_receipt_sha256) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention receipt is immutable'; END IF; ELSEIF NEW.ordinary_usage_retention_receipt_json IS NOT NULL OR NEW.ordinary_usage_retention_receipt_sha256 IS NOT NULL THEN IF OLD.ordinary_usage_retention_source_json IS NULL OR OLD.ordinary_delete_seal_sha256 IS NULL OR NEW.ordinary_usage_retention_receipt_json IS NULL OR NEW.ordinary_usage_retention_receipt_sha256 IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.sourceSha256')) <> OLD.ordinary_usage_retention_source_sha256 OR JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.sealSha256')) <> OLD.ordinary_delete_seal_sha256 OR NOT EXISTS (SELECT 1 FROM usage_reconciliations r WHERE r.session_id=OLD.session_id AND r.tenant_id=OLD.tenant_id AND r.user_id=OLD.user_id AND r.deletion_generation=OLD.deletion_generation AND r.status='anonymized' AND r.checksum=JSON_UNQUOTE(JSON_EXTRACT(NEW.ordinary_usage_retention_receipt_json,'$.checksum'))) OR EXISTS (SELECT 1 FROM usage_ledger u WHERE u.session_id=OLD.session_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ordinary usage retention receipt requires same-transaction cutover'; END IF; END IF; END;
